import React, { useEffect, useState } from "react";
import Footer from "./Footer";
import Card from "./Card";
import Navbar from "./Navbar";
import { jwtDecode } from "jwt-decode";

function Shop({ onBuy, purchasedItems = {} }) {
  const [items, setItems] = useState([]);
  const [currentUserId, setCurrentUserId] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // 1. Get User ID (Matching the logic from your Dashboard component)
    const token = localStorage.getItem("token");
    if (token) {
      try {
        const decoded = jwtDecode(token);
        // Using _id as seen in your DashboardBooksList
        setCurrentUserId(decoded._id); 
      } catch (err) {
        console.error("Invalid token:", err);
      }
    }

    // 2. Fetch all books
    setLoading(true);
    fetch("http://localhost:5009/books")
      .then((res) => res.json())
      .then((data) => setItems(data))
      .catch((err) => console.error("Error fetching books:", err))
      .finally(() => setLoading(false));
  }, []);

  // Filter: Hide books that belong to the current user
  const filteredItems = items.filter((item) => {
    if (!currentUserId) return true;
    // Using item.userId (or item.user) vs currentUserId
    return String(item.userId) !== String(currentUserId);
  });

  if (loading) return (
    <>
      <Navbar />
      <div className="Body"><div className="HeadMo"><h1>Loading books...</h1></div></div>
      <Footer />
    </>
  );

  return (
    <>
      <Navbar />
      <div className="Body">
        {filteredItems.length === 0 ? (
          <div className="HeadMo"><h1>No books available!</h1></div>
        ) : (
          filteredItems.map((item) => {
            // CRITICAL FIX: Use _id instead of id
            const itemId = item._id; 
            const isPurchased = !!purchasedItems[itemId];

            return (
              <Card
                key={itemId}
                pic={item.pic}
                title={item.title}
                para={item.para}
                price={item.price}
              >
                <button
                  onClick={() => !isPurchased && onBuy(item)}
                  // Disabling the button makes it unclickable
                  disabled={isPurchased} 
                  style={{
                    // Style changes based on purchase state
                    backgroundColor: isPurchased ? "#808080" : "rgba(13, 110, 264, 1)",
                    color: "#fff",
                    borderRadius: "5px",
                    padding: "5px",
                    fontWeight: "100",
                    fontFamily: "Century Gothic",
                    width: "130px",
                    border: "none",
                    // Visual feedback for "unclickable" state
                    cursor: isPurchased ? "default" : "pointer",
                    opacity: isPurchased ? 0.6 : 1,
                    pointerEvents: isPurchased ? "none" : "auto" 
                  }}
                >
                  {isPurchased ? "Added to Cart" : "Add to Cart"}
                </button>
              </Card>
            );
          })
        )}
      </div>
      <Footer />
    </>
  );
}

export default Shop;
